	.size	card_defs, 4
card_defs:
	.zero	4
	.align	2
	.type	card_tpls, @object
	.size	card_tpls, 4
card_tpls:
	.zero	4
	.align	2
	.type	card_len, @object
	.size	card_len, 4
card_len:
	.zero	4
	.align	2
	.type	tpl_len, @object
	.size	tpl_len, 4
tpl_len:
	.zero	4
	.local	tpl_cache
	.comm	tpl_cache,65536,1
	.globl	brain_set_counts
	.align	2
	.type	brain_set_counts, @object
	.size	brain_set_counts, 16
brain_set_counts:
	.zero	16
	.local	buf
	.comm	buf,65536,1
	.local	iob
	.comm	iob,4096,1
	.local	fobj
	.comm	fobj,24,1
	.align	2
	.type	snapped, @object
	.size	snapped, 4
snapped:
	.zero	4
	.local	desc
	.comm	desc,256,2
	.align	2
	.type	table_len, @object
	.size	table_len, 4
table_len:
